import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Versionen und Kompatibilität","description":"Versionsregeln, Datenmigrationen und sichere Updates für ATLAS und Plugins.","frontmatter":{"title":"Versionen und Kompatibilität","description":"Versionsregeln, Datenmigrationen und sichere Updates für ATLAS und Plugins."},"headers":[],"relativePath":"projects/atlas-plugins/developers/compatibility.md","filePath":"projects/atlas-plugins/developers/compatibility.md","lastUpdated":1792862028000}'),a={name:"projects/atlas-plugins/developers/compatibility.md"};function s(d,e,o,l,u,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="versionen-und-kompatibilitat" tabindex="-1">Versionen und Kompatibilität <a class="header-anchor" href="#versionen-und-kompatibilitat" aria-label="Permalink to &quot;Versionen und Kompatibilität&quot;">​</a></h1><p>Diese Veröffentlichungsregeln gelten seit dem 15. Oktober 2026. App 0.1.302 ergänzt die automatische Prüfung vor Plugin-Installationen und Updates; 0.1.303 erkennt zusätzlich die verbundene HA-Version. Bestehende Installationen und Datenformate werden nicht migriert.</p><h2 id="welche-version-zahlt" tabindex="-1">Welche Version zählt? <a class="header-anchor" href="#welche-version-zahlt" aria-label="Permalink to &quot;Welche Version zählt?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Bedeutung</th></tr></thead><tbody><tr><td>ATLAS App/Runtime</td><td>Version des ausgelieferten Docker-, App/Add-on- oder Linux-Pakets.</td></tr><tr><td>HA-Integration</td><td>Version von <code>atlas_frontend</code>; ein HACS-Commit wird zusätzlich erfasst.</td></tr><tr><td>Framework</td><td>Eigene Version je <code>@atlas/*</code>-Paket; kein Ersatz für die App-Version.</td></tr><tr><td>Plugin</td><td>Eigene Version bei stabiler Plugin-ID; Manifest, Katalog und Paket müssen übereinstimmen.</td></tr><tr><td>Datenformat</td><td>Art und Formatversion gespeicherter Daten; eine Revision zählt Änderungen für die Konfliktprüfung.</td></tr></tbody></table><p>Der Card Editor wird mit ATLAS ausgeliefert. Externe Plugins werden unabhängig aktualisiert. Gleiche Versionsnummern verschiedener Komponenten beweisen keine Kompatibilität.</p><h2 id="veroffentlichungsregeln" tabindex="-1">Veröffentlichungsregeln <a class="header-anchor" href="#veroffentlichungsregeln" aria-label="Permalink to &quot;Veröffentlichungsregeln&quot;">​</a></h2><p>Verwende <code>MAJOR.MINOR.PATCH</code>: PATCH für kompatible Fehlerkorrekturen, MINOR für kompatible Funktionen, ab einer stabilen 1.x-Schnittstelle MAJOR für Vertragsbrüche. Vor 1.0 erfordert ein Vertragsbruch eine neue MINOR-Version und Migrationshinweise. Künftige inkompatible Änderungen dürfen deshalb nicht als weiterer 0.1.x-Patch erscheinen. Bestehende Versionen werden nicht umbenannt.</p><p>Alpha-Versionen sind ausdrücklich Teststände. Geänderte veröffentlichte Pakete erhalten eine neue Version; reine Dokumentationsänderungen brauchen keine Laufzeitversion. Halte Quell-Commit und geprüfte Kombinationen in den Release-Notizen fest.</p><h2 id="was-pruft-atlas-heute" tabindex="-1">Was prüft ATLAS heute? <a class="header-anchor" href="#was-pruft-atlas-heute" aria-label="Permalink to &quot;Was prüft ATLAS heute?&quot;">​</a></h2><p>Repository-Angaben <code>compatibility.atlas</code>, <code>host</code> und <code>homeAssistant</code> beschreiben beanspruchte Kompatibilität. <code>atlas</code> bezieht sich auf die App/Runtime. Seit 0.1.302 prüft der Server die Angaben aus Katalog, Paket und enthaltenem Manifest vor dem Ersetzen gemeinsam. SemVer-Bereiche wie <code>&gt;=0.1.302 &lt;0.2.0</code> werden ausgewertet. Ein bekannter Widerspruch oder eine ungültige Voraussetzung blockiert das Paket; die installierte Version bleibt erhalten. Fehlende Angaben bedeuten <strong>ungeprüft</strong> und erfordern eine ausdrückliche Bestätigung. Bestehende Plugins werden nicht deaktiviert.</p><p><code>host</code> akzeptiert einen Namen oder eine Liste von Alternativen. <code>administration-local</code> bleibt der historische Name für den gemeinsamen Node-Installer; <code>docker</code>, <code>linux</code> und <code>homeassistant</code> passen zum konfigurierten Bereitstellungsziel. Die Bestätigung kann bekannte Inkompatibilität nicht übergehen. Die Vorschau schreibt keine Dateien; beim tatsächlichen Installieren prüft der Server erneut. Auch lokale Paketimporte werden geprüft.</p><p>Seit 0.1.303 fragt die Administration die HA-Version über die authentifizierte <code>/api/config</code>-Antwort der konfigurierten Verbindung ab. Token und sonstige HA-Konfiguration bleiben im Backend. Bei HA-Anforderungen wird vor Vorschau und Installation neu abgefragt; eine Version aus dem Browser wird nicht übernommen. Fehlende Zugangsdaten, Zeitüberschreitungen, Weiterleitungen, verweigerter Zugriff oder ungültige Antworten bleiben <strong>unbekannt</strong> und erfordern eine ausdrückliche Prüfung. Ein alter erfolgreicher Wert wird nicht weiterverwendet. Beta-, RC- und Entwicklungsversionen bleiben Vorabversionen. Unbekannte Metadatenfelder benötigen weiterhin eine Prüfung. Der lesende Endpunkt <code>/api/homeassistant/version</code> liefert nur bereinigte Versionsmetadaten oder einen festen Fehlergrund; er verändert keine Einstellungen oder Projekte.</p><p>Die Update-Anzeige vergleicht Versionstexte numerisch; sie ist kein vollständiger SemVer-Prüfer. Kernel-Modulabhängigkeiten unterstützen separat exakte Zahlentripel, <code>^</code> und <code>*</code>, aber keine allgemeinen Bereiche oder Vorabversionen. Der aktuelle Caret-Abgleich hält bei Version 0 die MINOR-Version gleich; <code>^0.0.3</code> akzeptiert dabei auch <code>0.0.4</code>. Nutze für solche Module exakte Versionen.</p><p>Paket- und Manifest-ID sowie Version werden vor dem Ersetzen geprüft; beim Repository-Update muss auch die Katalogversion stimmen. Deklarierte Fähigkeiten sind keine automatischen Berechtigungen und keine Sandbox. Eine passende Versionsangabe ersetzt keinen Funktionstest oder eine Vertrauensprüfung des Plugins.</p><h2 id="daten-erhalten-und-wiederherstellen" tabindex="-1">Daten erhalten und wiederherstellen <a class="header-anchor" href="#daten-erhalten-und-wiederherstellen" aria-label="Permalink to &quot;Daten erhalten und wiederherstellen&quot;">​</a></h2><ol><li>Sichere vor Updates HA und ATLAS-Daten beziehungsweise die eigenständige Installation mit Daten und Installationsidentität. Exportiere lokale Admin-Einstellungen, Editor-Projekte und gemeinsame Plugin-Metadaten zusätzlich. Externe Plugin-Daten und browserlokale Sammlungen brauchen eigene Sicherungen.</li><li>Behalte Laufzeitadresse, persistente Datenpfade und Identität bei. Verschlüsselte Einstellungen sind dadurch nicht automatisch auf andere Installationen übertragbar. Eine Quellcode-Sicherung ersetzt kein Datenbackup.</li><li>Aktualisiere eine Komponente nach der anderen; starte HA nach Integrationsupdates wie beschrieben neu. Prüfe anschließend Einstellungen, Projekte und aktive Plugins.</li><li>Stelle bei Bedarf passenden Programmstand <strong>und</strong> den dazugehörigen Datenstand wieder her. Ein älteres Programm darf neuere unbekannte Formate nicht überschreiben.</li></ol><p>Für künftige Datenmigrationen gelten: Vorschau ohne Schreibzugriff, Original sichern, Kopie umwandeln und validieren, ausdrücklich übernehmen, Konflikte prüfen und atomar ersetzen. Unbekannte oder beschädigte Formate dürfen nicht durch leere Daten ersetzt werden. Wiederholungen und Fehler müssen ohne Datenverlust behandelt werden. Diese Regeln sind Anforderungen, keine Behauptung einer bereits vorhandenen universellen Migration.</p><p>Ab ATLAS 0.1.304 bleibt vor jedem Ersetzen eine geprüfte Paket-Rücksicherung unter <code>&lt;ATLAS_PLUGIN_DATA_ROOT&gt;/.recovery</code> im vorhandenen persistenten Datenpfad erhalten. Dieser Bereich ist nicht als öffentliche Plugin-Datei erreichbar. Im Plugin-Manager ersetzt „Paket importieren“ ein vorhandenes Plugin erst nach Vorschau und „Sichern und übernehmen“. „Wiederherstellen“ zeigt gespeicherte Versionen zur Auswahl. Versionsrichtung und Fähigkeiten sind sichtbar; ungeklärte Kompatibilität braucht eine bewusste Bestätigung, bekannte Inkompatibilität sperrt die Übernahme. Veraltete Vorschauen werden abgewiesen. Dateien und gemeinsamer Plugin-Eintrag werden zusammen übernommen; Aktivierung und Repositories bleiben erhalten. Auch vor einer Wiederherstellung wird die gerade installierte Version gesichert.</p><p>Diese Funktion stellt Plugin-Code wieder her. Zugangsdaten, Editor-Projekte, Browser-Sammlungen und Plugin-Datenformate werden nicht zurückgesetzt oder migriert. Vollständige Backups und passende Datenstände bleiben erforderlich. Grenzen je Plugin: 300 Dateien/20 MB pro Sicherung, insgesamt 256 MiB und 200 Sicherungen. Es gibt keine automatische Bereinigung; bei vollen oder unlesbaren Sicherungen wird das Ersetzen gesperrt. Der integrierte Card Editor wird weiterhin nur mit ATLAS aktualisiert. Die nativen Oberflächenprüfungen sind im folgenden Prüfumfang dokumentiert.</p><h2 id="geprufter-umfang" tabindex="-1">Geprüfter Umfang <a class="header-anchor" href="#geprufter-umfang" aria-label="Permalink to &quot;Geprüfter Umfang&quot;">​</a></h2><p>Der echte HACS-Integrationswechsel 0.1.301 → 0.1.306 und HA-Neustarts sind auf Pi 5 und Proxmox mit erhaltenen Einstellungen, Projekten und Plugins geprüft. Isoliert bestehen auch Rückkehr und erneutes Update. Das Konfigurationsformat bleibt 1.1; ein unbekanntes Format 1.2 wird ohne Umschreiben abgewiesen. Die Integration ist gegen HA 2026.10.1 sowie zusätzlich isoliert gegen 2026.9.4 geprüft. Weitere Versionen und echte Umwandlungen zwischen unterschiedlichen Datenformaten bleiben offen. Neue Migrationen brauchen Tests mit alten, aktuellen und unbekannten Formaten, Fehlerfällen, Konflikten und Wiederherstellung.</p><p>Die Paket-Wiederherstellung in der Oberfläche ist zuerst isoliert und danach auf Pi 5 und Proxmox für Icon Bibliothek, File Studio und Terminal geprüft. Originaldateien, Projekte, andere Plugins und geprüfte Einstellungen bleiben erhalten. Das ist keine generische Rückmigration beliebiger Plugin-Daten. Die getrennte vollständige HAOS-Wiederherstellung mit Papierkorb/Historie und geänderter IP ist im <a href="./../file-studio">File-Studio-Leitfaden</a> dokumentiert.</p><p>Die technische <a href="https://github.com/rockbaer2007/atlas/blob/main/docs/project/specifications/VERSION_COMPATIBILITY_POLICY.md" target="_blank" rel="noreferrer">Versionsrichtlinie im Quellrepository</a> beschreibt die Regeln und Grenzen genauer.</p>',23)])])}const b=n(a,[["render",s]]);export{c as __pageData,b as default};
